public class PassDemo {
  static void changeInt(int n)      { n = 99; }
  static void changeArr(int[] a)    { a[0] = 99; }
  static void reassignArr(int[] a)  { a = new int[]{7, 7}; }
  static void changeSb(StringBuilder sb) { sb.append("!"); }
  static void reassignSb(StringBuilder sb) { sb = new StringBuilder("new"); }

  public static void main(String[] args) {
    int n = 1;
    changeInt(n);
    System.out.println(n);            // 1

    int[] arr = {1, 2};
    changeArr(arr);
    System.out.println(arr[0]);       // 99

    int[] arr2 = {1, 2};
    reassignArr(arr2);
    System.out.println(arr2[0]);      // 1

    StringBuilder sb = new StringBuilder("hi");
    changeSb(sb);
    System.out.println(sb);           // hi!

    StringBuilder sb2 = new StringBuilder("hi");
    reassignSb(sb2);
    System.out.println(sb2);          // hi
  }
}

