// Pool Puzzle 完整答案
public class Puzzle4 {
    public static void main(String [] args) {
        Value[] values = new Value[6];
        int number = 1;
        int i = 0;
        while (i < 6) {
            values[i] = new Value();
            values[i].intValue = number;   // 依次存 1,10,100,1000,10000,100000
            number = number * 10;
            i = i + 1;
        }
        int result = 0;
        i = 6;
        while (i > 0) {
            i = i - 1;
            result = result + values[i].doStuff(i);  // 实参是 i
        }
        System.out.println("result " + result);      // result 543345
    }
}
class Value {
    int intValue;
    public int doStuff(int factor) {
        if (intValue > 100) return intValue * factor;      // 严格大于
        else return intValue * (5 - factor);
    }
}

